<template><view class="p"><view class="nav"><text @click="back">‹</text><text>监控面板</text><text @click="load">⟳</text></view><view class="grid"><view class="card" v-for="s in stats" :key="s.label"><text class="v">{{s.value}}</text><text class="l">{{s.label}}</text></view></view><view class="panel"><text class="title">账号维度</text><view class="row" v-for="a in accounts" :key="a.id"><text>{{a.nickname||a.username||('账号 '+a.id)}}</text><text>{{a.status||'-'}}</text></view></view></view></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{getDashboard,getAccountStats}from'@/api/dashboard';const stats=ref<any[]>([]),accounts=ref<any[]>([]);async function load(){try{const d:any=await getDashboard();stats.value=[{label:'账号',value:d?.accountCount??d?.accounts??0},{label:'商品',value:d?.productCount??d?.products??0},{label:'订单',value:d?.orderCount??d?.orders??0},{label:'消息',value:d?.messageCount??d?.messages??0}];const r:any=await getAccountStats({page:1,size:20});accounts.value=Array.isArray(r)?r:(r?.records||[])}catch(e:any){uni.showToast({title:e?.message||'加载失败',icon:'none'})}}function back(){uni.navigateBack({fail:()=>uni.switchTab({url:'/pages/profile/index'})})}onMounted(load)</script>
<style scoped lang="scss">.p{min-height:100vh;background:#f5f5f7}.nav{height:88rpx;background:#fff;display:flex;align-items:center;justify-content:space-between;padding:0 24rpx;font-size:32rpx;font-weight:700}.nav text:first-child{font-size:48rpx;color:#6b7280}.nav text:last-child{font-size:34rpx;color:#4f46e5}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16rpx;padding:24rpx}.card,.panel{background:#fff;border-radius:24rpx;padding:28rpx}.v{display:block;font-size:44rpx;font-weight:800;color:#4f46e5}.l{font-size:22rpx;color:#9ca3af}.panel{margin:0 24rpx}.title{font-weight:700;font-size:30rpx}.row{display:flex;justify-content:space-between;padding:18rpx 0;border-bottom:1rpx solid #f3f4f6;color:#4b5563}</style>